{"content": "import os

keep = {"gbrain-install.log"}
removed, failed = [], []
for name in sorted(os.listdir("/workspace")):
    if name in keep:
        continue
    path = os.path.join("/workspace", name)
    if os.path.isfile(path):
        try:
            os.remove(path)
            removed.append(name)
        except OSError as e:
            failed.append((name, str(e)))

print("removed:", len(removed))
for n in removed:
    print(" -", n)
if failed:
    print("failed:", failed)
print("remaining:", sorted(os.listdir("/workspace")))
", "path": "/workspace/.cleanup.py"}
